CREATE TABLE postulaciones (
	id INTEGER NOT NULL, 
	vacante_id INTEGER NOT NULL, 
	candidato_id INTEGER NOT NULL, 
	perfil JSON NOT NULL, 
	score FLOAT NOT NULL, 
	apto BOOLEAN NOT NULL, 
	desglose JSON NOT NULL, 
	razones JSON NOT NULL, 
	alertas JSON NOT NULL, 
	etapa VARCHAR(30) NOT NULL, 
	sugerencia VARCHAR(30) NOT NULL, 
	motivo_sugerencia VARCHAR(300) NOT NULL, 
	origen VARCHAR(30) NOT NULL, 
	creada DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(vacante_id) REFERENCES vacantes (id), 
